#include <cstdint>
#include <unordered_map>

enum class St { PendingNew, Working, PartiallyFilled, Filled, Cancelled, Rejected, PendingCancel };

struct WorkingOrder {
    uint64_t clid;        // unique client order id (idempotency key)
    uint64_t exch_id = 0; // assigned on ack
    int32_t  tick; uint32_t leaves; uint32_t filled = 0; bool buy;
    St state = St::PendingNew;
    uint64_t sent_ts;
};

class OMS {
public:
    uint64_t place(bool buy, int32_t tick, uint32_t qty) {
        uint64_t clid = next_clid_++;
        orders_[clid] = {clid, 0, tick, qty, 0, buy, St::PendingNew, now()};
        session_.send_new(clid, buy, tick, qty);    // reliable session
        return clid;
    }
    void on_ack(uint64_t clid, uint64_t exch_id) {
        if (auto* o = find(clid)) { o->exch_id = exch_id; if (o->state==St::PendingNew) o->state=St::Working; }
    }
    void on_fill(uint64_t clid, uint32_t qty) {
        if (auto* o = find(clid)) {
            o->filled += qty; o->leaves -= qty;
            o->state = o->leaves ? St::PartiallyFilled : St::Filled;
            position_ += o->buy ? (int64_t)qty : -(int64_t)qty;   // true position
            if (o->state==St::Filled) /* keep for audit, drop from working set */;
        }
    }
    void on_reject(uint64_t clid) { if (auto* o = find(clid)) o->state = St::Rejected; }
    void on_cancel_reject(uint64_t clid) { /* likely already filled: trust fills/drop-copy */ }
private:
    WorkingOrder* find(uint64_t clid){ auto it=orders_.find(clid); return it==orders_.end()?nullptr:&it->second; }
    static uint64_t now();
    std::unordered_map<uint64_t, WorkingOrder> orders_;
    uint64_t next_clid_ = 1; int64_t position_ = 0;
    struct Session { void send_new(uint64_t,bool,int32_t,uint32_t); } session_;
};

#include <vector>
#include <algorithm>

struct VenueQuote { int venue; int32_t price; uint32_t size; int32_t fee_ticks; uint32_t lat_ns; };

// Plan an aggressive BUY of `qty`: take cheapest effective price first.
std::vector<std::pair<int,uint32_t>>
plan_sweep(std::vector<VenueQuote> asks, uint32_t qty) {
    // effective cost = price + fee (rebate negative); break ties by lower latency
    std::sort(asks.begin(), asks.end(), [](auto&a, auto&b){
        int32_t ea = a.price + a.fee_ticks, eb = b.price + b.fee_ticks;
        return ea != eb ? ea < eb : a.lat_ns < b.lat_ns;
    });
    std::vector<std::pair<int,uint32_t>> children;
    for (auto& v : asks) {
        if (qty == 0) break;
        uint32_t take = std::min(qty, v.size);
        children.push_back({v.venue, take});       // child order per venue
        qty -= take;
    }
    return children;   // sent in parallel; track as children of the parent order
}
